import json
import re

from .ast import Add, Array, Comma, Filter, Format, Identity, Iterate, Limit, Literal, Pipe, Raise, StringTemplate
from .errors import CompileError
from .lexer import tokenize


def parse(source: str) -> Filter:
    """Compile source into a filter or raise :class:`CompileError`."""
    tokenize(source)
    text = _without_comments(source).strip()
    if not text:
        raise CompileError("empty program")
    if text.startswith("(") and text.endswith(")") and _matching_outer_parens(text):
        return parse(text[1:-1])
    if text == ".":
        return Identity()
    if text == ".[]":
        return Iterate()
    if text == "error":
        return Raise()
    pipe = _top_level_separator(text, "|")
    if pipe is not None:
        return Pipe(parse(text[:pipe]), parse(text[pipe + 1:]))
    if text.startswith("@"):
        match = re.fullmatch(r"@([A-Za-z_][A-Za-z_0-9]*)(?:\s+(.*))?", text, re.DOTALL)
        if match:
            return Format(match.group(1), _parse_template(match.group(2)) if match.group(2) else None)
    if text.startswith("strflocaltime(") and text.endswith(")"):
        return parse(text[len("strflocaltime("):-1])
    plus = _top_level_separator(text, "+")
    if plus is not None:
        return Add(parse(text[:plus]), parse(text[plus + 1:]))
    if text.startswith("[") and text.endswith("]"):
        return Array(parse(text[1:-1]))
    if text.startswith("limit(") and text.endswith(")"):
        body = text[6:-1]
        separator = _top_level_separator(body, ";")
        if separator is not None:
            count_text, expression = body[:separator], body[separator + 1 :]
            if count_text.strip().isdigit():
                return Limit(int(count_text.strip()), parse(expression))
    comma = _top_level_comma(text)
    if comma is not None:
        return Comma(parse(text[:comma]), parse(text[comma + 1 :]))
    if text in {"nan", "infinite", "-infinite", "-nan"}:
        return Literal({"nan": float("nan"), "infinite": float("inf"),
                        "-infinite": float("-inf"), "-nan": float("nan")}[text])
    if text.startswith('"') and text.endswith('"'):
        return _parse_template(text)
    if re.fullmatch(r"(?:-?(?:0|[1-9]\d*)(?:\.\d+)?(?:[eE][+-]?\d+)?)|true|false|null", text):
        try:
            return Literal(json.loads(text))
        except json.JSONDecodeError as error:
            raise CompileError(f"invalid literal: {error.msg}") from error
    raise CompileError("unsupported program in foundational parser")

def _parse_template(text: str) -> StringTemplate:
    if not text or text[0] != '"' or text[-1] != '"': raise CompileError("invalid string")
    parts: list[str | Filter] = []
    start = position = 1
    while position < len(text) - 1:
        if text[position:position + 2] == "\\(":
            if start < position: parts.append(json.loads('"' + text[start:position] + '"'))
            end = _matching_paren(text, position + 1)
            parts.append(parse(text[position + 2:end]))
            position = end + 1; start = position
        else: position += 1
    if start < len(text) - 1: parts.append(json.loads('"' + text[start:-1] + '"'))
    return StringTemplate(tuple(parts))

def _matching_paren(text: str, opening: int) -> int:
    depth = 0; quoted = escaped = False
    for position in range(opening + 1, len(text)):
        character = text[position]
        if quoted:
            if escaped: escaped = False
            elif character == "\\": escaped = True
            elif character == '"': quoted = False
        elif character == '"': quoted = True
        elif character == "(": depth += 1
        elif character == ")":
            if depth == 0: return position
            depth -= 1
    raise CompileError("unterminated interpolation")

def _matching_outer_parens(text: str) -> bool:
    depth = 0; quoted = escaped = False
    for position, character in enumerate(text):
        if quoted:
            if escaped: escaped = False
            elif character == "\\": escaped = True
            elif character == '"': quoted = False
        elif character == '"': quoted = True
        elif character == "(": depth += 1
        elif character == ")":
            depth -= 1
            if depth == 0: return position == len(text) - 1
    return False


def _without_comments(source: str) -> str:
    """Remove comments while preserving hashes inside JSON strings."""
    result: list[str] = []
    quoted = False
    escaped = False
    in_comment = False
    for character in source:
        if in_comment:
            if character == "\n":
                in_comment = False
                result.append(character)
            continue
        if quoted:
            result.append(character)
            if escaped:
                escaped = False
            elif character == "\\":
                escaped = True
            elif character == '"':
                quoted = False
        elif character == '"':
            quoted = True
            result.append(character)
        elif character == '#':
            in_comment = True
            result.append('\n')
        else:
            result.append(character)
    return "".join(result)


def _top_level_comma(text: str) -> int | None:
    return _top_level_separator(text, ",")


def _top_level_separator(text: str, separator: str) -> int | None:
    depth = 0
    quoted = False
    escaped = False
    for position, character in enumerate(text):
        if quoted:
            if escaped:
                escaped = False
            elif character == "\\":
                escaped = True
            elif character == '"':
                quoted = False
        elif character == '"':
            quoted = True
        elif character in "[{(":
            depth += 1
        elif character in "]})":
            depth -= 1
        elif character == separator and depth == 0:
            return position
    if quoted or depth != 0:
        raise CompileError("incomplete program")
    return None
"""Lexical scanner for jq source text."""

from dataclasses import dataclass
from enum import Enum, auto
import re

from .errors import CompileError


class TokenKind(Enum):
    IDENTIFIER = auto()
    NUMBER = auto()
    STRING = auto()
    FIELD = auto()
    BINDING = auto()
    FORMAT = auto()
    KEYWORD = auto()
    OPERATOR = auto()
    DELIMITER = auto()
    INTERPOLATION_START = auto()
    INTERPOLATION_END = auto()
    END = auto()
    IDENTITY = auto()


@dataclass(frozen=True)
class Token:
    kind: TokenKind
    text: str
    position: int


_KEYWORDS = {"as", "def", "module", "import", "include", "if", "then", "else", "elif", "and", "or", "end", "reduce", "foreach", "try", "catch", "label", "break"}
_OPERATORS = ("//=", "?//", "!=", "==", "|=", "+=", "-=", "*=", "/=", "%=", "<=", ">=", "..", "//")
_DELIMITERS = set(".?!=;,,:|+-*/%$<>{}[]()")
_NUMBER = re.compile(r"(?:[0-9]+(?:\.[0-9]*)?|\.[0-9]+)(?:[eE][+-]?[0-9]+)?")
_NAME = re.compile(r"[A-Za-z_][A-Za-z_0-9]*")
_QUALIFIED_NAME = re.compile(r"(?:[A-Za-z_][A-Za-z_0-9]*::)*[A-Za-z_][A-Za-z_0-9]*")


def _error(source: str, position: int, message: str) -> CompileError:
    line = source.count("\n", 0, position) + 1
    line_start = source.rfind("\n", 0, position) + 1
    return CompileError(f"{message} at line {line}, column {position - line_start + 1}")


def _scan_string(source: str, start: int) -> tuple[list[Token], int]:
    tokens = [Token(TokenKind.STRING, '"', start)]
    position = start + 1
    text_start = position
    while position < len(source):
        character = source[position]
        if character == "\\":
            if position + 1 >= len(source):
                raise _error(source, position, "unterminated string")
            if source[position + 1] == "(":
                if text_start < position:
                    tokens.append(Token(TokenKind.STRING, source[text_start:position], text_start))
                tokens.append(Token(TokenKind.INTERPOLATION_START, "\\(", position))
                expression_start = position + 2
                cursor = expression_start
                depth = 1
                quoted_expression = False
                escaped_expression = False
                while cursor < len(source):
                    current = source[cursor]
                    if quoted_expression:
                        if escaped_expression:
                            escaped_expression = False
                        elif current == "\\":
                            escaped_expression = True
                        elif current == '"':
                            quoted_expression = False
                    elif current == '"':
                        quoted_expression = True
                    elif current == "(":
                        depth += 1
                    elif current == ")":
                        depth -= 1
                        if depth == 0:
                            inner = tokenize(source[expression_start:cursor])
                            tokens.extend(inner[:-1])
                            tokens.append(Token(TokenKind.INTERPOLATION_END, ")", cursor))
                            position = cursor + 1
                            text_start = position
                            break
                    cursor += 1
                else:
                    raise _error(source, position, "unterminated interpolation")
                continue
            if source[position + 1] == "u":
                escape = source[position + 2:position + 6]
                if len(escape) != 4 or not re.fullmatch(r"[0-9A-Fa-f]{4}", escape):
                    raise _error(source, position, "invalid unicode escape")
                position += 6
            else:
                if source[position + 1] not in '"\\/bfnrt':
                    raise _error(source, position, "invalid escape")
                position += 2
            continue
        if character == '"':
            if text_start < position:
                tokens.append(Token(TokenKind.STRING, source[text_start:position], text_start))
            tokens.append(Token(TokenKind.STRING, '"', position))
            return tokens, position + 1
        if ord(character) < 0x20:
            raise _error(source, position, "control character in string")
        position += 1
    raise _error(source, start, "unterminated string")


def tokenize(source: str) -> list[Token]:
    """Tokenize jq source, retaining offsets and rejecting lexical errors."""
    tokens: list[Token] = []
    position = 0
    while position < len(source):
        character = source[position]
        if character.isspace():
            position += 1
            continue
        if character == "#":
            newline = source.find("\n", position)
            position = len(source) if newline < 0 else newline + 1
            continue
        if character == '"':
            string_tokens, position = _scan_string(source, position)
            tokens.extend(string_tokens)
            continue
        number = _NUMBER.match(source, position)
        if number:
            tokens.append(Token(TokenKind.NUMBER, number.group(), position))
            position = number.end()
            continue
        if character == "." and position + 1 < len(source) and source[position + 1].isalpha():
            name = _NAME.match(source, position + 1)
            assert name is not None
            tokens.append(Token(TokenKind.FIELD, source[position:name.end()], position))
            position = name.end()
            continue
        if character == "$":
            name = _QUALIFIED_NAME.match(source, position + 1)
            if not name:
                raise _error(source, position, "invalid binding")
            tokens.append(Token(TokenKind.BINDING, source[position:name.end()], position))
            position = name.end()
            continue
        if character == "@":
            name = _NAME.match(source, position + 1)
            if not name:
                raise _error(source, position, "invalid format")
            tokens.append(Token(TokenKind.FORMAT, source[position:name.end()], position))
            position = name.end()
            continue
        qualified = _QUALIFIED_NAME.match(source, position)
        if qualified:
            text = qualified.group()
            kind = TokenKind.KEYWORD if text in _KEYWORDS else TokenKind.IDENTIFIER
            tokens.append(Token(kind, text, position))
            position = qualified.end()
            continue
        operator = next((value for value in _OPERATORS if source.startswith(value, position)), None)
        if operator:
            tokens.append(Token(TokenKind.OPERATOR, operator, position))
            position += len(operator)
            continue
        if character in _DELIMITERS:
            kind = TokenKind.IDENTITY if character == "." else TokenKind.DELIMITER
            tokens.append(Token(kind, character, position))
            position += 1
            continue
        raise _error(source, position, "unexpected character")
    tokens.append(Token(TokenKind.END, "", len(source)))
    return tokens
"""Application-facing interpreter orchestration."""

import json
from collections.abc import Iterable, Iterator

from .evaluator import evaluate
from .parser import parse
from .runtime import JsonValue


class Interpreter:
    """Compile once, then evaluate each JSON input in order."""

    def __init__(self, program: str) -> None:
        self._compiled = parse(program)

    def run(self, inputs: Iterable[JsonValue]) -> Iterator[JsonValue]:
        """Yield every output, preserving input and generator ordering."""
        for value in inputs:
            yield from evaluate(self._compiled, value)


def parse_input(line: str) -> JsonValue:
    """Decode one JSON input value."""
    return json.loads(line.lstrip("\ufeff"), parse_constant=_parse_json_constant)


def parse_inputs(text: str) -> Iterator[JsonValue]:
    """Decode every whitespace-separated JSON value in an input stream.

    ``jq`` accepts JSON values separated by arbitrary whitespace, so a value may
    span multiple physical lines.  ``raw_decode`` preserves the boundary
    between successive values without requiring a non-standard JSON parser.
    """
    decoder = json.JSONDecoder(parse_constant=_parse_json_constant)
    position = 0
    while True:
        while position < len(text) and text[position].isspace():
            position += 1
        if position >= len(text):
            return
        if position == 0 and text.startswith("\ufeff"):
            position += 1
            continue
        value, position = decoder.raw_decode(text, position)
        yield value


def _parse_json_constant(value: str) -> float:
    """Decode jq's accepted non-standard numeric constants."""
    return {"NaN": float("nan"), "Infinity": float("inf"),
            "-Infinity": float("-inf")}[value]
"""Ordered generator evaluator boundary."""

from .ast import Add, Array, Comma, Filter, Format, Identity, Iterate, Limit, Literal, Pipe, Raise, StringTemplate
from .errors import RuntimeError
from .runtime import JsonValue, ValueStream, identity_stream


def evaluate(program: Filter, value: JsonValue) -> ValueStream:
    """Evaluate one input as an ordered stream of output values."""
    if isinstance(program, Identity):
        yield from identity_stream(value)
        return
    if isinstance(program, Iterate):
        if isinstance(value, list):
            yield from value
        elif isinstance(value, dict):
            yield from value.values()
        else:
            raise RuntimeError("cannot iterate over value")
        return
    if isinstance(program, Literal):
        yield program.value
        return
    if isinstance(program, Pipe):
        for intermediate in evaluate(program.left, value): yield from evaluate(program.right, intermediate)
        return
    if isinstance(program, Add):
        left = list(evaluate(program.left, value))
        right = list(evaluate(program.right, value))
        for first in left:
            for second in right:
                if isinstance(first, (int, float)) and isinstance(second, (int, float)):
                    yield first + second
                elif isinstance(first, str) and isinstance(second, str): yield first + second
                elif first is None: yield second
                elif second is None: yield first
                else: raise RuntimeError("cannot add values")
        return
    if isinstance(program, StringTemplate):
        pieces: list[str] = []
        for part in program.parts:
            pieces.append(part if isinstance(part, str) else "".join(_stringify(x) for x in evaluate(part, value)))
        yield "".join(pieces)
        return
    if isinstance(program, Format):
        if program.template is None: yield _apply_format(program.name, value)
        else:
            pieces: list[str] = []
            for part in program.template.parts:
                if isinstance(part, str): pieces.append(part)
                else:
                    pieces.extend(_apply_format(program.name, item) for item in evaluate(part, value))
            yield "".join(pieces)
        return
    if isinstance(program, Comma):
        yield from evaluate(program.left, value)
        yield from evaluate(program.right, value)
        return
    if isinstance(program, Raise):
        raise RuntimeError(program.message)
    if isinstance(program, Array):
        yield list(evaluate(program.expression, value))
        return
    if isinstance(program, Limit):
        outputs = iter(evaluate(program.expression, value))
        for _ in range(program.count):
            try:
                yield next(outputs)
            except StopIteration:
                break
        return
    raise RuntimeError("unknown compiled filter")

def _stringify(value: object) -> str:
    import json
    return value if isinstance(value, str) else json.dumps(value, separators=(",", ":"), ensure_ascii=False, allow_nan=False)

def _apply_format(name: str, value: object, template: bool = False) -> str:
    import base64, html, json, urllib.parse
    if name == "text": return _stringify(value)
    if name == "json": return json.dumps(value, separators=(",", ":"), ensure_ascii=False)
    if name == "html": return html.escape(_stringify(value), quote=True).replace("&#x27;", "&apos;")
    if name == "uri": return urllib.parse.quote(_stringify(value), safe="-_.~")
    if name == "urid": return urllib.parse.unquote(_stringify(value))
    if name == "base64": return base64.b64encode(_stringify(value).encode()).decode()
    if name == "base64d": return base64.b64decode(_stringify(value)).decode()
    if name == "csv": return ",".join('"' + str(x).replace('"', '""') + '"' if isinstance(x, str) else _stringify(x) for x in value)
    if name == "tsv": return "\t".join(_stringify(x).replace("\\", "\\\\").replace("\n", "\\n").replace("\r", "\\r").replace("\t", "\\t") for x in value)
    if name == "sh": return "'" + _stringify(value).replace("'", "'\\''") + "'"
    raise RuntimeError(f"unknown format @{name}")

def _node(node: Node, value: object, env: dict[str, object]) -> ValueStream:
    op, a = node.operation, node.arguments
    if op == "identity": yield value
    elif op == "literal":
        text=a[0]; yield {"true":True,"false":False,"null":None,"nan":float("nan"),"infinite":float("inf"),"-infinite":float("-inf"),"-nan":float("nan")}.get(text, json.loads(text))
    elif op == "string": yield _decode_string(a[0], value, env)
    elif op == "var":
        if a[0] not in env: raise RuntimeError(f"variable ${a[0]} is not defined")
        yield env[a[0]]
    elif op == "field": yield _index(value, a[0])
    elif op == "index":
        for base in _node(a[0],value,env): yield _index(base,a[1])
    elif op == "iterate":
        for base in _node(a[0],value,env):
            if isinstance(base,dict): yield from base.values()
            elif isinstance(base,list): yield from base
            else: raise RuntimeError("cannot iterate over value")
    elif op in ("indexexpr","slice"):
        return Node('unsupported',(w,))

def parse(source: str) -> Filter:
    tokenize(source)
    return Parser(source).parse()
